import request from '../utils/request';

// 首页统计
export const getChartData = params => {
    return request({
        url: 'chart-data',
        method: 'get',
        params: params
    });
};

export const getOrgTypeStats = params => {
    return request({
        url: 'org-type-stats',
        method: 'get',
        params: params
    });
};

