// 导出
export const getExport = params => {
    return request({
        url: 'export-excel',
        method: 'get',
        params: params,
        responseType: 'blob'
    });
};

// 导入
export const getImport = params => {
    return request({
        url: 'import',
        method: 'post',
        data: params,
    });
};


