import Vue from 'vue'
import Vuex from 'vuex'

Vue.use(Vuex)

export default new Vuex.Store({
  state: {
    calcHieght: '1',
  },
  getters: {
    calcHieght: (state) => state.calcHieght,
  },
  mutations: {
    CALC_HEIGHT(state, data) {
      state.calcHieght = data
    },
  },
  actions: {},
  modules: {},
})
